<script setup lang="ts">
import { onMounted, ref, watch } from 'vue'
import { NotebookPen, Plus, Search } from 'lucide-vue-next'
import Pager from '../components/Pager.vue'
import RecordTimeline from '../components/RecordTimeline.vue'
import Modal from '../components/Modal.vue'
import { api, isArchived, messageOf, notify, query, recordTypes, ui } from '../api'
import type { Attachment, Page, RecordEntry } from '../types'
const props=defineProps<{revision:number;initialQuery?:string}>();const emit=defineEmits<{record:[project:string];image:[a:Attachment,images:Attachment[]];edit:[record:RecordEntry];changed:[]}>()
const records=ref<RecordEntry[]>([]),project=ref(''),type=ref(''),search=ref(props.initialQuery||''),total=ref(0),offset=ref(0),loading=ref(false),error=ref('');const cursors=new Map<number,string>()
const limit=30
const unclassified=ref(false),selected=ref<string[]>([]),classifyOpen=ref(false),classifyProject=ref(''),classifying=ref(false),classifyError=ref(''),dateFrom=ref(''),dateTo=ref(''),tag=ref('')
async function load(){loading.value=true;error.value='';try{const page=await api<Page<RecordEntry>>(`/api/records?${query({project_id:project.value,type:type.value,q:search.value,unclassified:unclassified.value?'1':'',date_from:dateFrom.value,date_to:dateTo.value,tag:tag.value,limit,cursor:cursors.get(offset.value)})}`);records.value=page.items;total.value=page.total;selected.value=[];if(page.next_cursor)cursors.set(offset.value+limit,page.next_cursor)}catch(e){error.value=messageOf(e)}finally{loading.value=false}}
onMounted(load);watch(()=>props.revision,load);watch([project,type,unclassified],()=>{cursors.clear();offset.value=0;void load()});watch(()=>props.initialQuery,q=>{search.value=q||'';offset.value=0;void load()});function page(next:number){offset.value=next;void load()}
function toggle(id:string){selected.value=selected.value.includes(id)?selected.value.filter(x=>x!==id):[...selected.value,id]}
async function classify(){if(!classifyProject.value||!selected.value.length||classifying.value)return;classifying.value=true;classifyError.value='';try{await api('/api/records/batch-classify',{method:'POST',body:JSON.stringify({items:records.value.filter(r=>selected.value.includes(r.id)).map(r=>({id:r.id,version:r.version})),project_id:classifyProject.value})});classifyOpen.value=false;notify('所选记录已归类');emit('changed');await load()}catch(e){classifyError.value=messageOf(e)+'；本批次未写入。'}finally{classifying.value=false}}
async function openEntity(id:string){try{emit('edit',await api<RecordEntry>(`/api/records/${id}`))}catch(e){notify(messageOf(e),true)}}
defineExpose({openEntity})
</script>
<template><div class="page-heading"><div><h1>工作记录</h1><p class="page-description">沿着时间，找回每一次发现和决定。</p></div><button class="button primary" :disabled="isArchived(project)" @click="emit('record',project)"><Plus :size="18"/>新增记录</button></div><form class="filter-bar" @submit.prevent="cursors.clear();offset=0;load()"><select v-model="project" aria-label="记录所属项目"><option value="">全部项目</option><option v-for="p in ui.projects" :key="p.id" :value="p.id">{{p.name}}</option></select><select v-model="type" aria-label="记录类型"><option value="">全部类型</option><option v-for="(name,key) in recordTypes" :key="key" :value="key">{{name}}</option></select><div class="input-with-icon"><Search :size="16"/><input v-model="search" placeholder="搜索记录内容或标签" aria-label="搜索记录"/></div><button type="submit" class="button subtle">查询</button><label class="checkbox-label inline"><input v-model="unclassified" type="checkbox"/>仅未归类</label><input v-model="dateFrom" type="date" aria-label="开始日期" class="filter-date"/><input v-model="dateTo" type="date" aria-label="结束日期" class="filter-date"/><input v-model="tag" placeholder="标签精确筛选" aria-label="标签筛选" class="filter-tag"/></form><div v-if="error" class="error-banner" role="alert">{{error}}<button class="text-button" @click="load">重试</button></div><section class="surface records-surface"><div class="section-heading records-heading"><div class="records-heading-title"><h2>记录时间线</h2><span class="muted">{{total}} 条记录</span></div><div class="record-selection-tools" role="toolbar" aria-label="记录批量操作"><span class="record-selection-count" role="status" aria-live="polite">已选 {{selected.length}} 条</span><button type="button" class="button primary small" :disabled="!selected.length||loading||classifying" @click="classifyOpen=true;classifyError=''">批量归类</button><button type="button" class="text-button" :disabled="!selected.length||loading||classifying" @click="selected=[]">取消选择</button></div></div><p v-if="loading" class="loading-message">正在读取记录…</p><div v-else-if="!records.length" class="empty-state"><NotebookPen :size="38"/><h2>留住现场的一手信息</h2><p>记录事实、附上图片、标记项目；需要时随时查回。</p><button class="button primary" :disabled="isArchived(project)" @click="emit('record',project)">写下第一条记录</button></div><div v-else class="timeline-wrap"><RecordTimeline :records="records" show-date selectable :selected="selected" @toggle="toggle" @edit="emit('edit',$event)" @image="(a,images)=>emit('image',a,images)"/></div><Pager :offset="offset" :limit="limit" :total="total" @change="page"/></section><Modal :open="classifyOpen" title="批量归类记录" @close="!classifying&&(classifyOpen=false)"><form class="modal-body" @submit.prevent="classify"><p class="input-hint">{{selected.length}} 条记录将归入同一项目。任意记录版本变化则整批不写入。</p><label>目标项目<select v-model="classifyProject" required><option value="" disabled>请选择项目</option><option v-for="p in ui.projects.filter(p=>p.status!=='archived')" :key="p.id" :value="p.id">{{p.name}}</option></select></label><p v-if="classifyError" class="form-error" role="alert">{{classifyError}}</p><div class="modal-footer"><button class="button primary" :disabled="classifying||!classifyProject">确认归类</button></div></form></Modal></template>

<style scoped>
.records-heading{gap:16px;min-height:74px}.records-heading-title{display:flex;align-items:center;gap:14px;min-width:0}.records-heading-title h2{white-space:nowrap}.records-heading-title .muted{white-space:nowrap}.record-selection-tools{display:grid;grid-template-columns:6.2em auto auto;align-items:center;gap:14px;flex-shrink:0;font-size:12px}.record-selection-count{font-variant-numeric:tabular-nums;white-space:nowrap;color:var(--muted)}.record-selection-tools button{white-space:nowrap}.record-selection-tools .text-button:disabled{color:var(--muted);opacity:.5;cursor:default}@media(max-width:1000px){.records-heading{display:grid;grid-template-columns:minmax(0,1fr);gap:12px;padding-top:16px;padding-bottom:16px}.records-heading-title{justify-content:space-between}.record-selection-tools{grid-template-columns:minmax(6.2em,1fr) auto auto;gap:12px;width:100%}}
</style>
